page.script:
// 触发事件
function CrrHandler(t) {
	// 新增事件
	if (t.id == "add") {
		var data = {prefixTitle: "新增"};
		handleRoute("depotForm", data);
	}
	// 修改事件
	if (t.id == "edit") {
		var records = Ext.getCmp("depotTreeList").getSelectionModel().getSelection();
		if (records.length != 1) {
			Ext.MessageBox.alert("提示", "请选择一行进行修改!");
			return false;
		}
		var data = {id: records[0].id, prefixTitle: "修改"};
		handleRoute("depotForm", data);
	}
	// 删除事件
	if (t.id == "delete") {
		var records = Ext.getCmp("depotTreeList").getSelectionModel().getSelection();
		if (records.length != 1) {
			Ext.MessageBox.alert("提示", "请选择一行进行删除!");
			return false;
		}
		handleDelConfirm("/webapi/archives/depot/delete", records, Ext.getCmp("depotTreeList"));
	}
	// 搜索事件
	if (t.id == "search") {
		Ext.getCmp('depotTreeList').getStore().load({params: {parentId: 'root'}});
	}
}
